-- Sales tax is now charged on the taxable lines only: tax-free lines are left out of what the tax is
-- worked out on. Rework the stored amount of draft invoices to match (subtotal less the discount, plus
-- the tax on the taxable lines less their discount). Invoices already sent keep the amount they were
-- issued for.
ALTER TABLE invoice ADD COLUMN rework_subtotal DECIMAL(14, 2);
ALTER TABLE invoice ADD COLUMN rework_taxable DECIMAL(14, 2);

UPDATE invoice i SET
    rework_subtotal = (SELECT COALESCE(SUM(ROUND(l.qty * l.unit_price, 2)), 0)
                       FROM invoice_line_item l WHERE l.invoice_id = i.id),
    rework_taxable = (SELECT COALESCE(SUM(ROUND(l.qty * l.unit_price, 2)), 0)
                      FROM invoice_line_item l WHERE l.invoice_id = i.id AND NOT l.tax_exempt)
WHERE i.status = 'DRAFT'
  AND EXISTS (SELECT 1 FROM invoice_line_item l WHERE l.invoice_id = i.id AND l.tax_exempt);

UPDATE invoice SET amount = rework_subtotal - ROUND(rework_subtotal * discount_pct / 100, 2)
        + ROUND((rework_taxable - ROUND(rework_taxable * discount_pct / 100, 2)) * tax_pct / 100, 2)
WHERE rework_subtotal IS NOT NULL;

ALTER TABLE invoice DROP COLUMN rework_subtotal;
ALTER TABLE invoice DROP COLUMN rework_taxable;
-- An invoice can add a second tax, a levy, on top of the sales tax. Like the sales tax it is a
-- percentage worked out on the taxable base (the taxable lines after the discount), and the stored
-- amount now includes it as well; existing invoices have no levy, so their amounts are unchanged.
ALTER TABLE invoice ADD COLUMN levy_pct DECIMAL(5, 2) DEFAULT 0 NOT NULL;

ALTER TABLE invoice ADD CONSTRAINT invoice_levy_pct_range CHECK (levy_pct >= 0 AND levy_pct <= 100);
-- A client's prices can already include tax. For such a client the sales tax and levy are worked back
-- out of the taxable lines instead of being added on top, so the invoice total is the discounted
-- subtotal. Each invoice carries whether it is priced tax-inclusive (taken from its client), so a
-- sent invoice keeps the figures it was issued with. Existing clients and invoices add tax on top,
-- as before, so no amounts change.
ALTER TABLE client ADD COLUMN tax_inclusive BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE invoice ADD COLUMN tax_inclusive BOOLEAN DEFAULT FALSE NOT NULL;
-- Each line is worked out and rounded to the cent first, then the lines are added up, so a unit price
-- can now be given to a fraction of a cent (up to four decimal places): two lines of 10.005 are 10.01
-- each and 20.02 together. The sales tax and levy are likewise worked out and rounded on each taxable
-- line (after its discount) and then added up. Rework the stored amount of draft invoices that add tax
-- on top to match; tax-inclusive drafts owe the discounted subtotal, which is unchanged, and invoices
-- already sent keep the amount they were issued for.
ALTER TABLE invoice_line_item ALTER COLUMN unit_price DECIMAL(14, 4);

ALTER TABLE invoice ADD COLUMN rework_subtotal DECIMAL(14, 2);
ALTER TABLE invoice ADD COLUMN rework_taxes DECIMAL(14, 2);

UPDATE invoice i SET
    rework_subtotal = (SELECT COALESCE(SUM(ROUND(l.qty * l.unit_price, 2)), 0)
                       FROM invoice_line_item l WHERE l.invoice_id = i.id),
    rework_taxes = (SELECT COALESCE(SUM(
                        ROUND((ROUND(l.qty * l.unit_price, 2)
                               - ROUND(ROUND(l.qty * l.unit_price, 2) * i.discount_pct / 100, 2)) * i.tax_pct / 100, 2)
                        + ROUND((ROUND(l.qty * l.unit_price, 2)
                               - ROUND(ROUND(l.qty * l.unit_price, 2) * i.discount_pct / 100, 2)) * i.levy_pct / 100, 2)), 0)
                    FROM invoice_line_item l WHERE l.invoice_id = i.id AND NOT l.tax_exempt)
WHERE i.status = 'DRAFT'
  AND NOT i.tax_inclusive
  AND EXISTS (SELECT 1 FROM invoice_line_item l WHERE l.invoice_id = i.id);

UPDATE invoice SET amount = rework_subtotal - ROUND(rework_subtotal * discount_pct / 100, 2) + rework_taxes
WHERE rework_subtotal IS NOT NULL;

ALTER TABLE invoice DROP COLUMN rework_subtotal;
ALTER TABLE invoice DROP COLUMN rework_taxes;
-- A whole client can be tax exempt: none of their invoices carry any sales tax or levy, whatever the
-- lines say. Each invoice carries whether it is tax exempt (taken from its client), so a sent invoice
-- keeps the figures it was issued with. Existing clients and invoices are taxed as before, so no
-- amounts change.
ALTER TABLE client ADD COLUMN tax_exempt BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE invoice ADD COLUMN tax_exempt BOOLEAN DEFAULT FALSE NOT NULL;

